// WhatsApp Bot — WhatsApp bot starter generated by EvilOS
// Pair-code auth. Run: npm start, then enter the printed code on WhatsApp.
const { default: makeWASocket, useMultiFileAuthState, fetchLatestBaileysVersion, Browsers, DisconnectReason } = require('@whiskeysockets/baileys');
const P = require('pino');
(async () => {
  const { state, saveCreds } = await useMultiFileAuthState('./sessions');
  const { version } = await fetchLatestBaileysVersion();
  const sock = makeWASocket({ logger: P({ level: 'silent' }), printQRInTerminal: false, browser: Browsers.macOS('Chrome'), auth: state, version });
  sock.ev.on('creds.update', saveCreds);
  sock.ev.on('connection.update', async (u) => {
    if (u.qr) return;
    if (u.connection === 'open') console.log('✅ connected as', sock.user.id);
    if (u.connection === 'close') {
      const code = u.lastDisconnect?.error?.output?.statusCode;
      if (code === DisconnectReason.loggedOut) { console.log('logged out — delete sessions/ and restart'); process.exit(0); }
      console.log('reconnecting...'); setTimeout(() => process.exit(1), 3000);
    }
  });
  sock.ev.on('messages.upsert', async ({ messages }) => {
    for (const m of messages) {
      if (!m.message || m.key.remoteJid === 'status@broadcast') continue;
      const text = m.message.conversation || m.message.extendedTextMessage?.text || '';
      if (text.startsWith('.ping')) await sock.sendMessage(m.key.remoteJid, { text: '🏓 pong!' }, { quoted: m });
    }
  });
})();
